const minutesInMonth = 30 * 24 * 60; // 43200
const sloFraction = 0.999;
const errorBudgetMin = minutesInMonth * (1 - sloFraction); // 43.2
const pagesPerWeek = 42;
const actionablePages = 12;
const pctActionable = (actionablePages / pagesPerWeek) * 100;
const burnPerMin1x = errorBudgetMin / minutesInMonth; // steady spend rate
const fastBurn = 6;
const shouldPage = fastBurn >= 6; // multi-window fast-burn alert pages at 6x
console.log('error_budget_min=' + errorBudgetMin.toFixed(1));
console.log('pct_actionable=' + pctActionable.toFixed(1));
console.log('burn_per_min_1x=' + burnPerMin1x.toFixed(4));
console.log('page_on_6x_burn=' + shouldPage);
